import{_ as h,C as r,o as d,c as l,aj as t,E as n,j as c}from"./chunks/framework.D04Qc2jV.js";const u="/public/agentbook/diagrams/recherche-workflow.png",z=JSON.parse('{"title":"Recherche und Wissensarbeit","description":"","frontmatter":{"title":"Recherche und Wissensarbeit"},"headers":[],"relativePath":"kapitel/05-recherche-und-wissensarbeit.md","filePath":"kapitel/05-recherche-und-wissensarbeit.md"}'),o={name:"kapitel/05-recherche-und-wissensarbeit.md"};function g(b,e,m,f,p,k){const i=r("Quiz"),s=r("Checklist"),a=r("FeedbackForm");return d(),l("div",null,[e[0]||(e[0]=t('<h1 id="kapitel-5-recherche-und-wissensarbeit" tabindex="-1">Kapitel 5: Recherche und Wissensarbeit <a class="header-anchor" href="#kapitel-5-recherche-und-wissensarbeit" aria-label="Permalink to &quot;Kapitel 5: Recherche und Wissensarbeit&quot;">​</a></h1><h2 id="von-der-offenen-frage-zum-belastbaren-briefing" tabindex="-1">Von der offenen Frage zum belastbaren Briefing <a class="header-anchor" href="#von-der-offenen-frage-zum-belastbaren-briefing" aria-label="Permalink to &quot;Von der offenen Frage zum belastbaren Briefing&quot;">​</a></h2><p>Sie wollen einen Blogartikel über ein Thema schreiben, das Sie nicht tief kennen. Oder Sie bereiten ein Kundengespräch vor und wollen verstehen, in welchem Marktumfeld Ihr Kunde gerade steckt. Oder Sie überlegen, ob ein neues Angebot Sinn ergibt, und brauchen dafür belastbare Informationen, keine Vermutungen.</p><p>Das sind klassische Situationen für Wissensarbeit. Und es sind Situationen, in denen KI-Agenten einen besonders großen Unterschied machen können, wenn man sie richtig einsetzt.</p><p>Aber auch Situationen, in denen sie besonders gefährlich sind, wenn man sie falsch einsetzt.</p><p>Dieser Abschnitt beginnt deshalb mit einer ehrlichen Einschätzung der Stärken und Grenzen von Agenten in der Recherche, bevor er zeigt, wie ein verlässlicher Rechercheablauf aufgebaut wird.</p><h2 id="was-agenten-in-der-recherche-konnen-und-was-nicht" tabindex="-1">Was Agenten in der Recherche können und was nicht <a class="header-anchor" href="#was-agenten-in-der-recherche-konnen-und-was-nicht" aria-label="Permalink to &quot;Was Agenten in der Recherche können und was nicht&quot;">​</a></h2><p>Agenten können schnell große Mengen an Text durchsuchen, zusammenfassen und strukturieren. Sie können Verbindungen zwischen Informationen herstellen, die Sie übersehen hätten. Sie können eine Recherche in einer Stunde abschließen, für die Sie selbst einen halben Tag gebraucht hätten. Und sie können Ergebnisse in einem konsistenten Format präsentieren, das direkt weiterverarbeitet werden kann.</p><p>Was Agenten in der Recherche nicht gut können: Sie können nicht zuverlässig einschätzen, ob eine Quelle vertrauenswürdig ist. Sie können falsche Informationen mit derselben Überzeugung präsentieren wie richtige. Sie können aktuelle Entwicklungen verpassen, wenn ihr Wissensstand nicht auf dem neuesten Stand ist. Und sie können die Bedeutung von Informationen für Ihren spezifischen Kontext nicht immer richtig einschätzen.</p><p>Das bedeutet: Agenten sind in der Recherche kein Ersatz für menschliches Urteilsvermögen. Sie sind ein Werkzeug, das die Vorarbeit erledigt, die anschließend von Ihnen geprüft, eingeordnet und bewertet wird.</p><p>Ein Agent, der eine perfekte Recherche liefert, die Sie blind übernehmen, ist gefährlicher als gar kein Recherche-Werkzeug. Ein Agent, der eine 80-Prozent-Recherche liefert, die Sie sorgfältig prüfen und vervollständigen, ist ein echter Zeitgewinn.</p><h2 id="das-grundprinzip-belastbarer-agentenrecherche" tabindex="-1">Das Grundprinzip belastbarer Agentenrecherche <a class="header-anchor" href="#das-grundprinzip-belastbarer-agentenrecherche" aria-label="Permalink to &quot;Das Grundprinzip belastbarer Agentenrecherche&quot;">​</a></h2><p>Gute Agentenrecherche folgt einem klaren Prinzip: Der Agent liefert strukturierte Informationen mit expliziten Unsicherheitsmarkierungen, und der Mensch entscheidet, was davon belastbar ist und was weiterer Prüfung bedarf.</p><p>Das klingt simpel, aber es hat praktische Konsequenzen für die Art, wie Sie Rechercheaufträge formulieren. Ein Rechercheauftrag, der den Agenten bittet, &quot;alles über Thema X herauszufinden&quot;, wird zu einer langen, unkritischen Liste führen. Ein Rechercheauftrag, der den Agenten bittet, &quot;acht bis zwölf belegbare Fakten zu Thema X mit Quellenangaben zu liefern und dabei explizit zu markieren, was unsicher oder widersprüchlich ist&quot;, wird zu einem deutlich nutzbareren Ergebnis führen.</p><p>Der Unterschied liegt in der Struktur des Auftrags. Je klarer Sie definieren, was Sie brauchen und in welcher Form, desto besser wird das Ergebnis.</p><h2 id="der-recherche-workflow-schritt-fur-schritt" tabindex="-1">Der Recherche-Workflow: Schritt für Schritt <a class="header-anchor" href="#der-recherche-workflow-schritt-fur-schritt" aria-label="Permalink to &quot;Der Recherche-Workflow: Schritt für Schritt&quot;">​</a></h2><p>Ein verlässlicher Recherche-Workflow für Selbständige besteht aus fünf Phasen.</p><p><img src="'+u+'" alt="Der fünfstufige Recherche-Workflow"></p><p>Die erste Phase ist die Auftragsformulierung. Sie definieren, was Sie wissen wollen, warum Sie es brauchen, was das Ergebnis leisten soll, in welchem Format es präsentiert werden soll und wie viel Zeit oder Ressourcen der Agent dafür verwenden darf. Eine knappe, klare Formulierung dieser fünf Punkte am Anfang spart mehr Zeit als jede Optimierung danach.</p><p>Die zweite Phase ist die Recherche durch den Agenten. Der Agent durchsucht verfügbare Quellen, das eigene Wissen sowie bei entsprechender MCP-Verbindung auch das aktuelle Web, liest relevante Inhalte, extrahiert Fakten, erkennt Muster und stellt Verbindungen her.</p><p>Die dritte Phase ist die strukturierte Ausgabe. Der Agent präsentiert das Ergebnis in dem Format, das Sie vorgegeben haben. Ein gut definiertes Standardformat für Recherchen enthält immer: ein Kurzfazit in zwei bis drei Sätzen, eine nummerierte Liste von belegbaren Fakten, eine Quellenangabe für jeden Fakt, eine separate Liste von Unsicherheiten und Widersprüchen sowie einen Vorschlag, wie die Ergebnisse weiterverwendet werden können.</p><p>Die vierte Phase ist die menschliche Prüfung. Sie lesen das Ergebnis durch, bewerten die Quellen, hinterfragen überraschende Aussagen, überprüfen Fakten, die besonders wichtig sind, und markieren, was Sie für belastbar halten und was Sie separat verifizieren müssen.</p><p>Die fünfte Phase ist die Weiterverarbeitung. Sie nutzen das geprüfte Ergebnis als Grundlage für das, was Sie eigentlich brauchen: den Artikelentwurf, die Kundenpräsentation, die Entscheidungsvorlage.</p><p>Diese fünf Phasen können für einfache Recherchen in einer halben Stunde durchlaufen werden. Für komplexe Recherchen dauert die menschliche Prüfungsphase länger, aber der Agent hat Ihnen trotzdem den größten Teil der Arbeit abgenommen.</p><p>Eine knappe Briefing-Vorlage, die Sie für jeden Rechercheauftrag wiederverwenden können:</p><ul><li><strong>Frage:</strong> Was genau will ich wissen?</li><li><strong>Zweck:</strong> Wofür brauche ich das Ergebnis – Artikel, Angebot, Entscheidung?</li><li><strong>Umfang:</strong> Wie viele Fakten, welche Tiefe, welcher Zeitrahmen?</li><li><strong>Quellen:</strong> Welche Quellen sind erlaubt, welche bevorzugt (primär vor sekundär)?</li><li><strong>Format:</strong> Wie soll das Ergebnis aussehen – Tabelle, Liste, Kurzfazit plus Belege?</li><li><strong>Unsicherheit:</strong> Jeder Fakt mit Vertrauensgrad und Quelle, Widersprüche getrennt ausweisen.</li></ul><h2 id="deep-research-wenn-der-agent-selbst-recherchiert" tabindex="-1">Deep Research: Wenn der Agent selbst recherchiert <a class="header-anchor" href="#deep-research-wenn-der-agent-selbst-recherchiert" aria-label="Permalink to &quot;Deep Research: Wenn der Agent selbst recherchiert&quot;">​</a></h2><p>Die genannten fünf Phasen beschreiben den Normalfall. Daneben haben mehrere Werkzeuge inzwischen einen eigenständigen Recherche-Modus, oft „Deep Research&quot; oder schlicht „Research&quot; genannt. Dabei zerlegt der Agent eine Fragestellung selbst in Teilfragen, durchsucht über mehrere Runden hinweg das Web und angebundene Quellen, gleicht Funde ab und liefert am Ende einen zusammenhängenden Bericht mit Quellenangaben. Solche Läufe dauern einige Minuten bis zu einer Dreiviertelstunde, weil der Agent nicht eine einzige Suche durchführt, sondern eine ganze Kette aus Suchen und Zwischenauswertungen.</p><p>Für Selbständige ist das besonders wertvoll bei größeren Fragen: einer Marktübersicht, einer fundierten Themenrecherche, einem Vergleich mehrerer Anbieter. Der entscheidende Vorteil gegenüber einem einfachen Prompt ist, dass der Bericht Quellen mitliefert, die direkt auf das Originalmaterial verweisen. Damit verlagert sich Ihre Arbeit von „selbst suchen&quot; zu „die richtigen Quellen prüfen&quot;.</p><p>Technisch braucht der Agent dafür Zugang zum Web. Bei Claude geschieht das über die Research-Funktion oder über angebundene MCP-Server und Integrationen, bei anderen Werkzeugen über vergleichbare Webzugänge. Ohne einen solchen Zugang bleibt der Agent auf seinen Trainingsstand beschränkt und kann aktuelle Entwicklungen nicht erfassen.</p><h2 id="quellenqualitat-das-entscheidende-thema" tabindex="-1">Quellenqualität: Das entscheidende Thema <a class="header-anchor" href="#quellenqualitat-das-entscheidende-thema" aria-label="Permalink to &quot;Quellenqualität: Das entscheidende Thema&quot;">​</a></h2><p>Das größte Risiko in der Agentenrecherche ist das unkritische Übernehmen von Informationen, die der Agent mit hoher Überzeugung präsentiert, obwohl ihre Grundlage unsicher ist.</p><p>KI-Agenten neigen dazu, Informationen zu präsentieren, als wären sie gesichert, auch wenn sie aus unsicheren Quellen stammen oder auf Schlussfolgerungen basieren, die der Agent selbst gezogen hat. Das liegt nicht an einer bösen Absicht, sondern an der Funktionsweise von Sprachmodellen: Sie sind darauf optimiert, kohärente, überzeugende Texte zu erzeugen. Unsicherheiten klingen sprachlich oft weniger überzeugend, weshalb sie manchmal unterschätzt oder weggelassen werden.</p><p>Wie groß das Risiko ist, lässt sich beziffern. Aktuelle Untersuchungen für 2026 verorten die Fehlerquote führender Modelle je nach Aufgabe zwischen rund drei und neunzehn Prozent. Das ist deutlich besser als noch zwei Jahre zuvor, aber eben nicht null. Besonders heikel sind erfundene Quellenangaben: KI-Systeme erzeugen mitunter Literaturverweise, die täuschend echt aussehen, mit plausiblen Autorennamen, gut geformten Kennnummern und glaubwürdigen Titeln, die aber schlicht nicht existieren. Solche Fälschungen erkennt man nicht am Schreibstil, sondern nur durch den Abgleich mit der echten Quelle.</p><p>Daraus folgt eine nüchterne Erkenntnis: Mit besserem Formulieren allein lässt sich das Problem nicht lösen. Wirksam ist nur die Erdung an echten Quellen, also der direkte Zugriff auf das Originalmaterial über Webzugang oder angebundene Datenbanken, kombiniert mit einer menschlichen Stichprobenprüfung. Ein Agent, der seine Aussagen mit abrufbaren Quellen belegt, ist für ernsthafte Recherche deshalb klar einem Agenten vorzuziehen, der nur aus dem Gedächtnis antwortet.</p><p>Die Lösung ist außerdem, den Agenten explizit anzuweisen, Unsicherheiten zu markieren. Ein Prompt wie &quot;Markiere jeden Fakt mit dem Vertrauensgrad hoch, mittel oder niedrig, und begründe niedrige Bewertungen kurz&quot; erzeugt deutlich transparentere Ergebnisse als ein Prompt, der nur nach Fakten fragt.</p><p>Zusätzlich sollten Sie für wichtige Recherchen unterscheiden, woher die Informationen stammen. Primärquellen sind Originalquellen: offizielle Dokumentationen, wissenschaftliche Studien, gesetzliche Texte, direkte Unternehmensaussagen. Sie sind in der Regel zuverlässiger als Sekundärquellen, die Originalquellen interpretieren oder zusammenfassen. Tertiärquellen, also Zusammenfassungen von Zusammenfassungen, sollten Sie in kritischen Recherchen so weit wie möglich vermeiden.</p><p>Ein Rechercheauftrag, der den Agenten explizit anweist, primäre Quellen zu bevorzugen und den Unterschied zu nachgeordneten Quellen zu kennzeichnen, liefert deutlich nützlichere Ergebnisse als ein allgemeiner Rechercheauftrag.</p><h2 id="wettbewerbsrecherche-ein-praktisches-beispiel" tabindex="-1">Wettbewerbsrecherche: Ein praktisches Beispiel <a class="header-anchor" href="#wettbewerbsrecherche-ein-praktisches-beispiel" aria-label="Permalink to &quot;Wettbewerbsrecherche: Ein praktisches Beispiel&quot;">​</a></h2><p>Nehmen wir ein konkretes Szenario, das viele Selbständige kennen: Sie wollen verstehen, wie Ihre drei wichtigsten Wettbewerber ihr Angebot positionieren, um Ihre eigene Positionierung zu schärfen.</p><p>Ein schlecht formulierter Rechercheauftrag: &quot;Recherchiere meine Wettbewerber.&quot;</p><p>Ein gut formulierter Rechercheauftrag: &quot;Recherchiere die Angebote und Kommunikation von Wettbewerber A, B und C. Ich brauche: erstens die Kernaussage ihrer Positionierung, wie sie sie selbst kommunizieren, zweitens die drei Hauptversprechen, die sie gegenüber Kunden machen, drittens die Zielgruppe, die sie ansprechen, und viertens Lücken, die ich in ihrer Kommunikation erkenne. Liefere die Ergebnisse als strukturierte Tabelle. Markiere alle Punkte, bei denen die Information unklar oder widersprüchlich ist. Nutze ausschließlich die öffentlichen Websites der drei Unternehmen als Quelle.&quot;</p><p>Der zweite Auftrag ist länger zu formulieren. Aber er liefert ein Ergebnis, das Sie direkt nutzen können, das klar in seiner Grundlage ist und das Ihnen eine fundierte Grundlage für eigene Entscheidungen gibt.</p><h2 id="marktrecherche-und-trendbeobachtung" tabindex="-1">Marktrecherche und Trendbeobachtung <a class="header-anchor" href="#marktrecherche-und-trendbeobachtung" aria-label="Permalink to &quot;Marktrecherche und Trendbeobachtung&quot;">​</a></h2><p>Eine der nützlichsten Anwendungen von Agenten in der Wissensarbeit ist das regelmäßige Beobachten von Markt- und Branchenentwicklungen.</p><p>Statt selbst täglich Branchenblogs, Newsletter und Websites zu lesen, können Sie einen Agenten beauftragen, relevante Entwicklungen in bestimmten Themenfeldern zu beobachten und Ihnen wöchentlich oder täglich ein strukturiertes Briefing zu liefern. Der Agent liest die Quellen, filtert nach Relevanz für Ihr Geschäftsfeld, fasst die wichtigsten Entwicklungen zusammen und markiert, was besondere Aufmerksamkeit verdient.</p><p>Eine wichtige Einschränkung dabei: Ein Agent ohne Webzugang ist auf sein trainingsdatenbasiertes Wissen beschränkt, das je nach Werkzeug und Modell unterschiedlich aktuell ist. Für Recherchen, bei denen Aktualität entscheidend ist, benötigt der Agent einen MCP-Server mit Webzugriff oder ein anderes Werkzeug, das aktuelle Inhalte abrufen kann. Prüfen Sie bei Ihrem Werkzeug, ob und wie Sie aktuellen Webzugriff einrichten können, bevor Sie zeitkritische Recherchen delegieren.</p><h2 id="lernnotizen-und-wissensmanagement" tabindex="-1">Lernnotizen und Wissensmanagement <a class="header-anchor" href="#lernnotizen-und-wissensmanagement" aria-label="Permalink to &quot;Lernnotizen und Wissensmanagement&quot;">​</a></h2><p>Eine oft übersehene Anwendung von Agenten in der Wissensarbeit ist das persönliche Wissensmanagement.</p><p>Als Selbständiger lernen Sie ständig Neues: durch Kundenprojekte, durch Fortbildungen, durch Artikel, durch Gespräche. Dieses Wissen verschwindet aber oft schnell wieder aus dem aktiven Gedächtnis, wenn es nicht strukturiert festgehalten wird.</p><p>Ein Agent kann dabei helfen, Lernnotizen aus rohem Material zu destillieren. Sie geben ihm einen Artikel, einen Podcast-Transkript oder Mitschriften aus einem Workshop, und er extrahiert die wichtigsten Erkenntnisse, stellt sie in einen Zusammenhang mit anderen relevanten Informationen aus Ihrem Wissensspeicher und bereitet sie in einem Format auf, das Sie später leicht wiederfinden.</p><p>Für Claude Code und Hermes lässt sich das in das Memory-System integrieren: Der Agent schreibt relevante Erkenntnisse direkt in Ihre Wissens- oder Projektdateien. So wächst Ihr persönliches Wissenssystem mit jeder Recherche und mit jedem Lernprozess weiter.</p><h2 id="der-faktencheck-schritt-nicht-uberspringen" tabindex="-1">Der Faktencheck-Schritt: Nicht überspringen <a class="header-anchor" href="#der-faktencheck-schritt-nicht-uberspringen" aria-label="Permalink to &quot;Der Faktencheck-Schritt: Nicht überspringen&quot;">​</a></h2><p>Abschließend noch einmal eine direkte Empfehlung: Überspringen Sie niemals den Faktencheck.</p><p>Wenn ein Agent eine Recherche geliefert hat, die Sie wichtig finden und die Sie als Grundlage für Kommunikation, Entscheidungen oder Veröffentlichungen nutzen wollen, prüfen Sie mindestens die drei wichtigsten Fakten darin an der Originalquelle. Das dauert fünf bis zehn Minuten und schützt Sie davor, falsche Informationen weiterzugeben.</p><p>Das Vertrauen in Agenten als Rechercheassistenten wächst mit der Zeit, wenn Sie regelmäßig Stichproben machen und dabei feststellen, dass die Informationen verlässlich sind. Es schwindet schnell, wenn eine nicht geprüfte Aussage sich als falsch herausstellt und bereits in einen Kundentext eingeflossen ist.</p><p>Ein gut genutzter Recherche-Agent macht Sie informierter, schneller und strukturierter. Ein schlecht genutzter Recherche-Agent gibt Ihnen das Gefühl von Gründlichkeit, ohne die tatsächliche Grundlage dafür zu liefern.</p><p>Den Unterschied macht nicht das Werkzeug. Den Unterschied macht die Qualität des Auftrags und die Konsequenz der Prüfung.</p><h2 id="interaktiv-recherche-check" tabindex="-1">Interaktiv: Recherche-Check <a class="header-anchor" href="#interaktiv-recherche-check" aria-label="Permalink to &quot;Interaktiv: Recherche-Check&quot;">​</a></h2>',59)),n(i,{question:"Was ist laut aktuellen Untersuchungen für 2026 die typische Fehlerquote führender Modelle?",options:["Unter einem Prozent","Je nach Aufgabe rund drei bis neunzehn Prozent","Über fünfzig Prozent"],answer:1,hint:"Deutlich besser als zwei Jahre zuvor, aber nicht null."}),n(i,{question:"Wie erkennt man eine vom Agenten erfundene Quellenangabe zuverlässig?",options:["Am Schreibstil","Durch den Abgleich mit der echten Quelle","Gar nicht"],answer:1,hint:"Erfundene Verweise sehen täuschend echt aus."}),e[1]||(e[1]=c("p",null,"Ihre Recherche-Checkliste – Fortschritt bleibt in diesem Browser gespeichert:",-1)),n(s,{"storage-key":"ch5-recherche",items:["Auftrag mit Frage, Zweck, Umfang, Quellen und Format formuliert","Primärquellen ausdrücklich vor Sekundärquellen verlangt","Jeden Fakt mit Vertrauensgrad und Quelle angefordert","Webzugang oder MCP sichergestellt, falls Aktualität zählt","Die drei wichtigsten Fakten an der Originalquelle geprüft"]}),e[2]||(e[2]=t('<h2 id="quellen" tabindex="-1">Quellen <a class="header-anchor" href="#quellen" aria-label="Permalink to &quot;Quellen&quot;">​</a></h2><ul><li>Anthropic: Claude – Research, Web-Suche und Integrationen (<code>claude.com/blog/integrations</code>)</li><li>Anthropic: Model Context Protocol – Connectors und Web-Suche (<code>modelcontextprotocol.io</code>)</li><li>AI Hallucination Rate Benchmarks 2026 (<code>digitalapplied.com/blog</code>)</li><li>STAT News: Steep rise in fraudulent citations in academic papers, 2026 (<code>statnews.com</code>)</li></ul>',2)),n(a)])}const S=h(o,[["render",g]]);export{z as __pageData,S as default};
